package com.example.pgck2;
import android.os.Bundle;
import android.content.Intent;
import android.graphics.Bitmap;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import com.google.firebase.auth.*;
import com.google.firebase.firestore.*;
import com.google.android.material.button.MaterialButton;
import com.google.zxing.*;
import com.google.zxing.qrcode.QRCodeWriter;
import java.util.*;

public class PremiumActivity extends AppCompatActivity {
 private LinearLayout body;private TextView status;private String uid;private boolean busy;
 private final FirebaseFirestore db=FirebaseFirestore.getInstance();
 @Override public void onCreate(Bundle state){super.onCreate(state);FirebaseUser user=FirebaseAuth.getInstance().getCurrentUser();if(user==null){startActivity(new Intent(this,LoginActivity.class));finish();return;}uid=user.getUid();LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(36,40,36,24);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);TextView title=new TextView(this);title.setText("PCGK Cinema\nPREMIUM");title.setTextSize(28);title.setTextColor(0xffffbd66);root.addView(title);status=new TextView(this);status.setTextColor(-1);root.addView(status);body=new LinearLayout(this);body.setOrientation(1);root.addView(body);button(root,"‹ Quay lại",()->finish());CinemaStyle.applyInsets(scroll);
  String order=getIntent().getData()==null?getPreferences(MODE_PRIVATE).getString(uid+"_pending",null):getIntent().getData().getLastPathSegment();if(order!=null&&order.matches("[A-Za-z0-9]{20}"))showOrder(order);else showPlans();
 }
 private void button(LinearLayout parent,String label,Runnable action){MaterialButton b=new MaterialButton(this);b.setText(label);b.setTextColor(-1);b.setCornerRadius(16);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff752f45));parent.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(!busy)action.run();});}
 private void plan(String id,String title,String price,int color){com.google.android.material.card.MaterialCardView card=new com.google.android.material.card.MaterialCardView(this);card.setCardBackgroundColor(color);card.setRadius(28);card.setStrokeColor(0xff665260);card.setStrokeWidth(2);LinearLayout content=new LinearLayout(this);content.setOrientation(1);content.setPadding(32,24,32,24);TextView heading=new TextView(this);heading.setText(title+"\n"+price);heading.setTextColor(0xffffd297);heading.setTextSize(23);content.addView(heading);TextView summary=new TextView(this);summary.setText("Mở nội dung Premium · thanh toán mô phỏng");summary.setTextColor(0xffbfc9d5);content.addView(summary);button(content,"Chọn gói này",()->create(id));card.addView(content);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=24;body.addView(card,p);}
 private void note(String value){TextView text=new TextView(this);text.setText(value);text.setTextColor(0xffd0c7d7);text.setTextSize(15);text.setPadding(0,20,0,20);body.addView(text);}
 private void showPlans(){body.removeAllViews();status.setText("Đang kiểm tra gói…");PremiumAccess.membership().addOnSuccessListener(order->{if(isFinishing())return;if(PremiumAccess.active(order)){status.setText("Premium đang hoạt động");note("Hết hạn: "+android.text.format.DateFormat.format("dd/MM/yyyy HH:mm",PremiumPlans.expires(order.getTimestamp("confirmedAt").toDate().getTime(),order.getString("plan"))));note("Bạn có thể mua gói mới sau khi gói hiện tại hết hạn.");return;}status.setText("Thanh toán mô phỏng · không thu tiền thật");note("Mở các video có nhãn Premium. QR quét được thật và chứa mã đơn nội bộ, không phải QR ngân hàng.");plan("month","Gói tháng · 30 ngày","49.000đ mô phỏng",0xff192b3b);plan("year","Gói năm · 365 ngày","399.000đ mô phỏng",0xff30213d);}).addOnFailureListener(e->{if(isFinishing())return;status.setText("Chưa tải được gói. Kiểm tra kết nối và Rules.");button(body,"Thử lại",this::showPlans);});}
 private void create(String plan){busy=true;status.setText("Đang tạo đơn mô phỏng…");DocumentReference ref=db.collection("premiumOrders").document();Map<String,Object> data=new HashMap<>();data.put("uid",uid);data.put("plan",plan);data.put("amount",PremiumPlans.price(plan));data.put("simulation",true);data.put("status","pending");data.put("createdAt",FieldValue.serverTimestamp());ref.set(data).addOnSuccessListener(v->{busy=false;getPreferences(MODE_PRIVATE).edit().putString(uid+"_pending",ref.getId()).apply();showOrder(ref.getId());}).addOnFailureListener(e->{busy=false;status.setText("Chưa tạo được đơn. Kiểm tra Rules và kết nối.");});}
 private void showOrder(String id){body.removeAllViews();status.setText("Đang tải đơn…");db.collection("premiumOrders").document(id).get(Source.SERVER).addOnSuccessListener(order->{if(isFinishing())return;if(!order.exists()||!uid.equals(order.getString("uid"))){status.setText("Không tìm thấy đơn của tài khoản này.");button(body,"Xem các gói",this::showPlans);return;}if("confirmed".equals(order.getString("status"))){getPreferences(MODE_PRIVATE).edit().remove(uid+"_pending").apply();showPlans();return;}status.setText("Đơn "+id);note(("year".equals(order.getString("plan"))?"Gói năm · 365 ngày":"Gói tháng · 30 ngày")+"\n"+order.getLong("amount")+"đ · MÔ PHỎNG");
  try{com.google.zxing.common.BitMatrix matrix=new QRCodeWriter().encode(PremiumPlans.qr(id),BarcodeFormat.QR_CODE,640,640);int[] pixels=new int[640*640];for(int y=0;y<640;y++)for(int x=0;x<640;x++)pixels[y*640+x]=matrix.get(x,y)?0xff000000:0xffffffff;Bitmap bitmap=Bitmap.createBitmap(pixels,640,640,Bitmap.Config.ARGB_8888);ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setContentDescription("QR mã đơn thanh toán mô phỏng "+id);body.addView(image,new LinearLayout.LayoutParams(-1,640));}catch(Exception e){note("Chưa tạo được QR.");}
  note(PremiumPlans.qr(id)+"\nQuét bằng camera sẽ đọc được liên kết đơn. QR không tự xác nhận thanh toán.");button(body,"Xác nhận thanh toán MÔ PHỎNG",()->confirm(id));button(body,"Chọn gói khác",()->{getPreferences(MODE_PRIVATE).edit().remove(uid+"_pending").apply();showPlans();});
 }).addOnFailureListener(e->status.setText("Không đọc được đơn. Kiểm tra kết nối và quyền truy cập."));}
 private void confirm(String id){busy=true;status.setText("Đang xác nhận mô phỏng…");DocumentReference order=db.collection("premiumOrders").document(id),subscription=db.collection("subscriptions").document(uid);db.runTransaction(tx->{DocumentSnapshot snapshot=tx.get(order);if(!snapshot.exists()||!uid.equals(snapshot.getString("uid")))throw new IllegalStateException("Invalid owner");if("confirmed".equals(snapshot.getString("status")))return null;DocumentSnapshot current=tx.get(subscription);String previous=current.getString("orderId");if(previous!=null&&PremiumAccess.active(tx.get(db.collection("premiumOrders").document(previous))))throw new IllegalStateException("Current plan active");tx.update(order,"status","confirmed","confirmedAt",FieldValue.serverTimestamp());Map<String,Object> data=new HashMap<>();data.put("orderId",id);data.put("updatedAt",FieldValue.serverTimestamp());tx.set(subscription,data);return null;}).addOnSuccessListener(v->{busy=false;if(isFinishing())return;getPreferences(MODE_PRIVATE).edit().remove(uid+"_pending").apply();body.removeAllViews();note("Đã xác nhận thanh toán mô phỏng. Không có tiền thật được chuyển.");showPlans();}).addOnFailureListener(e->{busy=false;if(!isFinishing())status.setText("Chưa xác nhận được. Gói hiện tại có thể còn hạn; kiểm tra Rules/kết nối rồi thử lại.");});}
}
